-- ─── audit.audit_logs ─────────────────────────────────────────
IF OBJECT_ID('audit.audit_logs','U') IS NULL
BEGIN
    CREATE TABLE audit.audit_logs (
        [id] BIGINT IDENTITY(1,1) NOT NULL,
        [organisation_id] BIGINT NOT NULL,
        [event_type] NVARCHAR(50) NOT NULL,
        [entity_type] NVARCHAR(100) NOT NULL,
        [entity_id] BIGINT,
        [entity_external_id] UNIQUEIDENTIFIER,
        [user_id] BIGINT,
        [username] NVARCHAR(100),
        [ip_address] NVARCHAR(45),
        [before_value_json] NVARCHAR(MAX),
        [after_value_json] NVARCHAR(MAX),
        [change_summary_en] NVARCHAR(500),
        [event_timestamp] DATETIME2 NOT NULL DEFAULT (sysutcdatetime()),
        [module] NVARCHAR(30) NOT NULL DEFAULT ('PLATFORM'),
        [chain_hash] NVARCHAR(64),
        CONSTRAINT [pk_audit_logs] PRIMARY KEY ([id])
    );
END;
GO
IF OBJECT_ID('audit.audit_logs') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'IX_audit_logs_org_ts' AND object_id = OBJECT_ID('audit.audit_logs'))
